"""Static Web console shell for VPSPC audit and managed maintenance."""

PAGE = r"""<!doctype html>
<html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>VPSPC 审计台</title>
<style>
:root{color-scheme:dark;--bg:#10151b;--surface:#18212b;--surface-2:#0d1319;--line:#334353;--text:#ecf2f7;--muted:#9baaba;--blue:#3387e8;--red:#d84d4d;--green:#46b983;--amber:#d49b31}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:14px system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;letter-spacing:0}main{max-width:1240px;margin:0 auto;padding:20px}.topbar{display:flex;align-items:center;justify-content:space-between;gap:16px;border-bottom:1px solid var(--line);padding-bottom:16px}.brand h1{font-size:22px;line-height:1.2;margin:0}.brand p{margin:5px 0 0;color:var(--muted)}.token{display:flex;align-items:center;gap:8px}.token label{color:var(--muted)}input,select{height:36px;background:var(--surface-2);border:1px solid var(--line);color:var(--text);border-radius:4px;padding:0 10px;font:inherit}input:focus,select:focus{outline:2px solid #4e9cff;outline-offset:1px}button{min-height:34px;border:1px solid #3d78b8;border-radius:4px;background:var(--blue);color:#fff;padding:0 12px;font:inherit;cursor:pointer}button:hover{filter:brightness(1.08)}button:disabled{opacity:.55;cursor:not-allowed}.secondary{background:transparent;border-color:var(--line);color:var(--text)}.danger{background:var(--red);border-color:#ef7070}.tabs{display:flex;gap:4px;border-bottom:1px solid var(--line);margin-top:14px}.tabs button{border:0;border-bottom:2px solid transparent;border-radius:0;background:transparent;color:var(--muted);padding:10px 13px}.tabs button[aria-selected="true"]{color:var(--text);border-bottom-color:var(--blue)}.view{padding:18px 0}.view[hidden]{display:none}.toolbar{display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin-bottom:14px}.split{display:grid;grid-template-columns:minmax(0,1fr) minmax(320px,1fr);gap:14px}.panel{border:1px solid var(--line);background:var(--surface);padding:14px}.panel h2{font-size:16px;margin:0 0 12px}.panel h3{font-size:14px;margin:18px 0 8px}.stats{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:8px;margin-bottom:14px}.stat{border:1px solid var(--line);background:var(--surface);padding:11px}.stat span{display:block;color:var(--muted)}.stat b{display:block;font-size:22px;margin-top:5px}table{width:100%;border-collapse:collapse}th,td{padding:9px 7px;text-align:left;border-bottom:1px solid var(--line);vertical-align:top}th{font-weight:600;color:var(--muted)}tr[data-incident]{cursor:pointer}tr[data-incident]:hover{background:#202c37}.detail{margin:0;white-space:pre-wrap;overflow:auto;max-height:560px;padding:12px;background:var(--surface-2);border:1px solid var(--line);font:12px ui-monospace,SFMono-Regular,Menlo,monospace}.muted{color:var(--muted)}.notice{border-left:3px solid var(--blue);padding:9px 10px;background:#152435;margin:10px 0}.warning{border-left-color:var(--amber);background:#312717}.danger-panel{border:1px solid #a94040;background:#2b1c22;padding:14px}.danger-panel h2{color:#ffaaaa}.node-list{max-height:360px;overflow:auto;border:1px solid var(--line);background:var(--surface-2)}.node-row{display:grid;grid-template-columns:28px minmax(160px,1fr) 110px 160px;gap:8px;align-items:center;padding:9px;border-bottom:1px solid var(--line)}.node-row:last-child{border:0}.node-row[data-online="false"]{opacity:.52}.actions{display:flex;gap:8px;flex-wrap:wrap;align-items:center}.hidden{display:none}.sev-critical,.sev-high{color:#ff8181}.sev-medium{color:#e7b653}.sev-low{color:#75d8a6}@media(max-width:800px){main{padding:14px}.topbar{align-items:flex-start;flex-direction:column}.split{grid-template-columns:1fr}.stats{grid-template-columns:repeat(2,minmax(0,1fr))}.node-row{grid-template-columns:26px minmax(110px,1fr) 90px} .node-row span:last-child{display:none}.token{width:100%}.token input{min-width:0;flex:1}th:nth-child(n+5),td:nth-child(n+5){display:none}}
</style></head><body><main>
<header class="topbar"><div class="brand"><h1>VPSPC 审计台</h1><p>行为审计、受管更新与受限清理</p></div><div class="token"><label for="token">Web Token</label><input id="token" type="password" autocomplete="off" spellcheck="false"><button class="secondary" id="connect">连接</button></div></header>
<nav class="tabs" aria-label="管理视图"><button data-view="audit" aria-selected="true">审计</button><button data-view="maintenance" aria-selected="false">更新管理</button><button data-view="destroy" aria-selected="false">彻底卸载</button></nav>
<section id="view-audit" class="view"><div class="toolbar"><button id="run-audit">立即巡查</button><span id="audit-status" class="muted"></span></div><div id="stats" class="stats"></div><div class="split"><section class="panel"><h2>行为事件</h2><div id="incidents" class="muted">等待连接。</div></section><section class="panel"><h2>报告 / 事件详情</h2><div id="ai-actions" class="actions hidden"><input id="question" placeholder="可选：向 AI 追问事件"><button id="review-ai">AI 复核</button></div><pre id="report" class="detail">等待连接。</pre></section></div></section>
<section id="view-maintenance" class="view" hidden><div class="toolbar"><button id="check-updates">检查更新</button><button class="secondary" id="toggle-version-check">切换每日检查</button><button class="secondary" id="refresh-maintenance">刷新</button><span id="maintenance-status" class="muted"></span></div><div id="maintenance-summary" class="panel muted">等待连接。</div><div class="split"><section class="panel"><h2>更新目标</h2><div class="actions"><select id="update-kind"><option value="controller_update">仅升级主控</option><option value="node_update">升级指定被控端</option><option value="all_update">升级主控＋全部在线被控端</option></select><select id="update-channel"><option value="stable">最新稳定版</option><option value="edge">最新测试版</option></select><select id="update-version" aria-label="指定正式版本"><option value="">使用所选通道最新版本</option></select></div><h3>在线被控端</h3><div class="actions"><button class="secondary" id="select-online">选择全部在线节点</button><button class="secondary" id="clear-nodes">清空选择</button></div><div id="node-list" class="node-list"></div><div id="update-confirm" class="notice hidden"></div><div class="actions"><button id="prepare-update">查看升级确认</button><button id="start-update" class="hidden">确认升级</button></div></section><section class="panel"><h2>当前任务</h2><pre id="maintenance-job" class="detail">当前没有维护任务。</pre><div class="actions"><button class="secondary" id="cancel-job">取消未开始任务</button></div></section></div></section>
<section id="view-destroy" class="view" hidden><section class="danger-panel"><h2>彻底卸载</h2><p>仅清理 VPSPC 明确拥有且管理标记匹配的程序、服务、配置、密钥、状态、缓存和日志。不会修改 Xray、sing-box、V2Board、妙妙屋 X、xrayagent 或它们的任何服务、配置和日志。</p><div class="actions"><select id="destroy-kind"><option value="node_destroy">彻底卸载指定在线被控端</option><option value="full_destroy">彻底卸载主控＋全部在线被控端</option></select><button class="danger" id="prepare-destroy">生成确认码</button></div><div id="destroy-nodes" class="node-list"></div><div id="destroy-confirm" class="notice hidden"></div><div class="actions hidden" id="destroy-code-row"><input id="destroy-code" inputmode="numeric" maxlength="6" placeholder="输入 6 位确认码"><button class="danger" id="start-destroy">确认开始清理</button></div><div class="actions hidden" id="final-destroy-row"><button class="danger" id="prepare-final-destroy">生成主控最终确认码</button></div></section></section>
</main><script>
let token='',currentIncident='',maintenance=null,preparedUpdate=null,preparedDestroy=null,activeView='audit',pollTimer=null;
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function setStatus(id,text){$(id).textContent=text||''}function showError(error){setStatus('#maintenance-status',error.message||String(error))}
async function api(path,options={}){const response=await fetch(path,{...options,headers:{'X-Web-Token':token,...(options.headers||{})}});const body=await response.json().catch(()=>({error:'服务器返回无效响应'}));if(!response.ok)throw new Error(body.error||'请求失败');return body}
function selectView(view){activeView=view;document.querySelectorAll('[data-view]').forEach(button=>button.setAttribute('aria-selected',String(button.dataset.view===view)));document.querySelectorAll('.view').forEach(section=>section.hidden=section.id!=='view-'+view);if(view==='maintenance'||view==='destroy')loadMaintenance()}
document.querySelectorAll('[data-view]').forEach(button=>button.onclick=()=>selectView(button.dataset.view));
$('#connect').onclick=async()=>{token=$('#token').value.trim();if(!token)return;try{await loadAudit();setStatus('#audit-status','已连接')}catch(error){setStatus('#audit-status',error.message)}};
async function loadAudit(){const [health,report,incidents]=await Promise.all([api('/api/health'),api('/api/report'),api('/api/incidents')]);const summary=report.summary||{};$('#stats').innerHTML=[['状态',health.status],['事件',summary.event_count||0],['发现',summary.finding_count||0],['用户',summary.user_count||0]].map(([label,value])=>'<div class="stat"><span>'+esc(label)+'</span><b>'+esc(value)+'</b></div>').join('');$('#report').textContent=JSON.stringify(report,null,2);$('#incidents').innerHTML=incidents.length?'<table><tr><th>ID</th><th>用户</th><th>等级</th><th>规则</th><th>节点</th><th>时间</th></tr>'+incidents.map(item=>'<tr data-incident="'+esc(item.incident_id)+'"><td>'+esc(item.incident_id)+'</td><td>'+esc(item.user)+'</td><td class="sev-'+esc(item.severity)+'">'+esc(item.severity)+'</td><td>'+esc(item.rule_id)+'</td><td>'+esc(item.node_name||item.node_id||'-')+'</td><td>'+esc(item.generated_at)+'</td></tr>').join('')+'</table>':'暂无事件';document.querySelectorAll('[data-incident]').forEach(row=>row.onclick=()=>loadIncident(row.dataset.incident));}
async function loadIncident(id){currentIncident=id;$('#ai-actions').classList.remove('hidden');$('#report').textContent=JSON.stringify(await api('/api/incidents/'+encodeURIComponent(id)),null,2)}
$('#run-audit').onclick=async()=>{const button=$('#run-audit');button.disabled=true;try{await api('/api/run',{method:'POST'});await loadAudit()}catch(error){setStatus('#audit-status',error.message)}finally{button.disabled=false}};
$('#review-ai').onclick=async()=>{if(!currentIncident)return;const button=$('#review-ai');button.disabled=true;try{$('#report').textContent=JSON.stringify(await api('/api/incidents/'+encodeURIComponent(currentIncident)+'/ai',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({question:$('#question').value})}),null,2)}catch(error){setStatus('#audit-status',error.message)}finally{button.disabled=false}};
function jobText(job){if(!job)return '当前没有维护任务。';const result=job.result||{},nodes=result.nodes||{},items=Object.values(nodes),done=items.filter(item=>['success','failed','rolled_back','expired','cancelled','safely_retained','skipped'].includes(item.status));const failures=items.filter(item=>!['success','skipped'].includes(item.status));let text='类型：'+(job.kind||'-')+'\n状态：'+(job.status||'-')+'\n节点进度：'+done.length+'/'+items.length+'，失败：'+failures.length;failures.slice(0,8).forEach(item=>text+='\n失败：'+(item.node_name||item.node_id)+' | '+(item.from_version||'unknown')+' -> '+(item.target_version||result.target_version||'-')+' | '+(item.stage||item.status));return text}
function renderNodes(nodes,target){target.innerHTML=nodes.map(node=>'<label class="node-row" data-online="'+Boolean(node.online)+'"><input type="checkbox" value="'+esc(node.node_id)+'" '+(!node.online?'disabled':'')+'><b>'+esc(node.name||node.node_id)+'</b><span>'+esc(node.agent_version||'未知版本')+'</span><span>'+esc(node.online?'在线':'离线')+'</span></label>').join('')||'<div class="muted">没有已注册被控端。</div>'}
function selected(selector){return [...document.querySelectorAll(selector+' input[type=checkbox]:checked')].map(box=>box.value)}
function renderMaintenance(snapshot){maintenance=snapshot;const catalog=snapshot.catalog||{},stable=catalog.stable||{},edge=catalog.edge||{},pref=snapshot.preferences||{};$('#maintenance-summary').innerHTML='主控版本：<b>'+esc(snapshot.controller_version)+'</b>　部署方式：<b>'+esc(snapshot.deployment_mode)+'</b>　稳定版：<b>'+esc(stable.version||'尚未检查')+'</b>　测试版：<b>'+esc(edge.version||'尚未检查')+'</b>　在线节点：<b>'+esc(snapshot.online_node_count||0)+'</b>　每日检查：<b>'+esc(pref.version_check_enabled?'开启':'关闭')+'</b>';const version=$('#update-version'),previous=version.value;version.innerHTML='<option value="">使用所选通道最新版本</option>'+((catalog.releases||[]).map(item=>'<option value="'+esc(item.version)+'">指定 '+esc(item.version)+'</option>').join(''));version.value=[...version.options].some(option=>option.value===previous)?previous:'';renderNodes(snapshot.nodes||[],$('#node-list'));renderNodes(snapshot.nodes||[],$('#destroy-nodes'));$('#maintenance-job').textContent=jobText(snapshot.job);$('#final-destroy-row').classList.toggle('hidden',!(snapshot.job&&snapshot.job.status==='awaiting_controller_confirmation'));$('#check-updates').textContent=snapshot.update_available?'检测到可用更新':'检查更新';}
async function loadMaintenance(){if(!token)return;try{const data=await api('/api/maintenance/status');renderMaintenance(data.status);setStatus('#maintenance-status','')}catch(error){showError(error)}}
function maintenanceStartBody(action){const kind=action||$('#update-kind').value;return {action:kind,channel:$('#update-channel').value,version:$('#update-version').value||null,node_ids:kind==='node_update'?selected('#node-list'):[]}}
$('#check-updates').onclick=async()=>{try{await api('/api/maintenance/check',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});await loadMaintenance()}catch(error){showError(error)}};
$('#toggle-version-check').onclick=async()=>{try{await api('/api/maintenance/preferences',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({version_check_enabled:!(maintenance.preferences||{}).version_check_enabled})});await loadMaintenance()}catch(error){showError(error)}};
$('#refresh-maintenance').onclick=loadMaintenance;$('#select-online').onclick=()=>document.querySelectorAll('#node-list input:not(:disabled)').forEach(box=>box.checked=true);$('#clear-nodes').onclick=()=>document.querySelectorAll('#node-list input').forEach(box=>box.checked=false);
$('#prepare-update').onclick=()=>{const body=maintenanceStartBody();if(body.action==='node_update'&&!body.node_ids.length){showError(new Error('请选择至少一台在线被控端'));return}preparedUpdate=body;$('#update-confirm').textContent='将执行 '+({'controller_update':'主控更新','node_update':'指定被控端更新','all_update':'主控与全部在线被控端更新'}[body.action])+'，目标版本：'+(body.version||body.channel)+'。相关 VPSPC 服务会短暂重启；被控端失败会自动回滚。';$('#update-confirm').classList.remove('hidden');$('#start-update').classList.remove('hidden')};
$('#start-update').onclick=async()=>{if(!preparedUpdate)return;try{await api('/api/maintenance/start',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(preparedUpdate)});preparedUpdate=null;$('#update-confirm').classList.add('hidden');$('#start-update').classList.add('hidden');await loadMaintenance();schedulePoll()}catch(error){showError(error)}};
$('#cancel-job').onclick=async()=>{try{await api('/api/maintenance/cancel',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});await loadMaintenance()}catch(error){showError(error)}};
$('#destroy-kind').onchange=()=>{const full=$('#destroy-kind').value==='full_destroy';$('#destroy-nodes').classList.toggle('hidden',full)};
$('#prepare-destroy').onclick=async()=>{const action=$('#destroy-kind').value,nodeIds=action==='node_destroy'?selected('#destroy-nodes'):[];if(action==='node_destroy'&&!nodeIds.length){showError(new Error('请选择至少一台在线被控端'));return}try{const response=await api('/api/maintenance/confirmation',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action})});preparedDestroy={action,node_ids:nodeIds,confirmation_id:response.confirmation.id};$('#destroy-confirm').innerHTML='确认码：<b>'+esc(response.confirmation.code)+'</b>　请手动输入此 6 位确认码以继续。';$('#destroy-confirm').classList.remove('hidden');$('#destroy-code-row').classList.remove('hidden');$('#destroy-code').value=''}catch(error){showError(error)}};
$('#start-destroy').onclick=async()=>{if(!preparedDestroy)return;const code=$('#destroy-code').value.trim();try{if(preparedDestroy.action==='controller_destroy'){await api('/api/maintenance/confirm-controller-destroy',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({confirmation_id:preparedDestroy.confirmation_id,confirmation_code:code})})}else{await api('/api/maintenance/start',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...preparedDestroy,confirmation_code:code})})}preparedDestroy=null;$('#destroy-code-row').classList.add('hidden');$('#destroy-confirm').classList.add('hidden');$('#start-destroy').textContent='确认开始清理';await loadMaintenance();schedulePoll()}catch(error){showError(error)}};
$('#prepare-final-destroy').onclick=async()=>{try{const response=await api('/api/maintenance/confirmation',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'controller_destroy'})});preparedDestroy={action:'controller_destroy',confirmation_id:response.confirmation.id};$('#destroy-confirm').innerHTML='主控最终确认码：<b>'+esc(response.confirmation.code)+'</b>　确认后管理台将离线。';$('#destroy-confirm').classList.remove('hidden');$('#destroy-code-row').classList.remove('hidden');$('#destroy-code').value='';$('#start-destroy').textContent='确认清理主控'}catch(error){showError(error)}};
function schedulePoll(){clearTimeout(pollTimer);if(!maintenance||!maintenance.job||['success','failed','rolled_back','cancelled','safely_retained','completed_with_failures','blocked_before_controller_destroy'].includes(maintenance.job.status))return;pollTimer=setTimeout(async()=>{await loadMaintenance();schedulePoll()},2000)}
</script></body></html>"""
